16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "address_line1")
43	    private String addressLine1;
44	
45	    @Column(name = "address_line2")
46	    private String addressLine2;
47	
48	    public String getAddressLine1() {
49	        return this.addressLine1;
50	    }
51	
52	    public void setAddressLine1(String addressLine1) {
53	        this.addressLine1 = addressLine1;
54	    }
55	
56	    public String getAddressLine2() {
57	        return this.addressLine2;
58	    }
59	
60	    public void setAddressLine2(String addressLine2) {
61	        this.addressLine2 = addressLine2;
62	    }
63	
64	    @Column(name = "city")
65	    @NotEmpty
66	    private String city;
67	
68	    @Column(name = "telephone")
69	    @NotEmpty
70	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
71	    private String telephone;
72	
73	    @Column(name = "email")
74	    private String email;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    public String getPostcode() {
80	        return this.postcode;
81	    }
82	
83	    public void setPostcode(String postcode) {
84	        this.postcode = postcode;
85	    }
86	
87	    @Column(name = "registration_date")
88	    private LocalDate registrationDate;
89	
90	    @Column(name = "birth_date")
91	    private LocalDate birthDate;
92	
93	    public LocalDate getBirthDate() {
94	        return this.birthDate;
95	    }
96	
97	    public void setBirthDate(LocalDate birthDate) {
98	        this.birthDate = birthDate;
99	    }
100	
101	    @Column(name = "title")
102	    private String title;
103	
104	    public String getTitle() {
105	        return this.title;
106	    }
107	
108	    public void setTitle(String title) {
109	        this.title = title;
110	    }
111	
112	    @Column(name = "deleted")
113	    private Boolean deleted = Boolean.FALSE;
114	
115	    public Boolean getDeleted() {
116	        return this.deleted;
117	    }
118	
119	    public void setDeleted(Boolean deleted) {
120	        this.deleted = deleted;
121	    }
122	
123	    @Column(name = "customer_code")
124	    private String customerCode;
125	
126	    @Column(name = "namesake_count")
127	    private Integer namesakeCount;
128	
129	    @Column(name = "household_size")
130	    private Integer householdSize;
131	
132	    public String getCustomerCode() {
133	        return this.customerCode;
134	    }
135	
136	    public void setCustomerCode(String customerCode) {
137	        this.customerCode = customerCode;
138	    }
139	
140	    public Integer getNamesakeCount() {
141	        return this.namesakeCount;
142	    }
143	
144	    public void setNamesakeCount(Integer namesakeCount) {
145	        this.namesakeCount = namesakeCount;
146	    }
147	
148	    public Integer getHouseholdSize() {
149	        return this.householdSize;
150	    }
151	
152	    public void setHouseholdSize(Integer householdSize) {
153	        this.householdSize = householdSize;
154	    }
155	
156	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
157	    private Set<Pet> pets;
158	
159	    public String getEmail() {
160	        return this.email;
161	    }
162	
163	    public void setEmail(String email) {
164	        this.email = email;
165	    }
166	
167	    public LocalDate getRegistrationDate() {
168	        return this.registrationDate;
169	    }
170	
171	    public void setRegistrationDate(LocalDate registrationDate) {
172	        this.registrationDate = registrationDate;
173	    }
174	
175	    public String getAddress() {
176	        return this.address;
177	    }
178	
179	    public void setAddress(String address) {
180	        this.address = address;
181	    }
182	
183	    public String getCity() {
184	        return this.city;
185	    }
186	
187	    public void setCity(String city) {
188	        this.city = city;
189	    }
190	
191	    public String getTelephone() {
192	        return this.telephone;
193	    }
194	
195	    public void setTelephone(String telephone) {
196	        this.telephone = telephone;
197	    }
198	
199	    protected Set<Pet> getPetsInternal() {
200	        if (this.pets == null) {
201	            this.pets = new HashSet<>();
202	        }
203	        return this.pets;
204	    }
205	
206	    protected void setPetsInternal(Set<Pet> pets) {
207	        this.pets = pets;
208	    }
209	
210	    public List<Pet> getPets() {
211	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
212	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
213	        return Collections.unmodifiableList(sortedPets);
214	    }
215	
216	    public void setPets(List<Pet> pets) {
217	        this.pets = new HashSet<>(pets);
218	    }
219	
220	    public void addPet(Pet pet) {
221	        getPetsInternal().add(pet);
222	        pet.setOwner(this);
223	    }
224	
225	    /**
226	     * Return the Pet with the given name, or null if none found for this Owner.
227	     *
228	     * @param name to test
229	     * @return true if pet name is already in use
230	     */
231	    public Pet getPet(String name) {
232	        return getPet(name, false);
233	    }
234	
235	    /**
236	     * Return the Pet with the given name, or null if none found for this Owner.
237	     *
238	     * @param name to test
239	     * @return true if pet name is already in use
240	     */
241	    public Pet getPet(String name, boolean ignoreNew) {
242	        name = name.toLowerCase();
243	        for (Pet pet : getPetsInternal()) {
244	            if (!ignoreNew || !pet.isNew()) {
245	                String compName = pet.getName();
246	                compName = compName.toLowerCase();
247	                if (compName.equals(name)) {
248	                    return pet;
249	                }
250	            }
251	        }
252	        return null;
253	    }
254	
255	    public Pet getPet(Integer petId) {
256	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
257	    }
258	
259	    @Override
260	    public String toString() {
261	        return new ToStringCreator(this)
262	
263	            .append("id", this.getId())
264	            .append("new", this.isNew())
265	            .append("lastName", this.getLastName())
266	            .append("firstName", this.getFirstName())
267	            .append("address", this.address)
268	            .append("city", this.city)
269	            .append("telephone", this.telephone)
270	            .toString();
271	    }
272	}
