1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.advice.OwnerIdentityKey;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "apiVersion", constant = "2")
26	    @Mapping(target = "identity", expression = "java(toIdentity(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerFiscalYear.label(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerMembershipLevel.points(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerMembershipLevel.of(owner))")
30	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerMemberId.region(owner))")
31	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerTimezone.of(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
33	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerAgeBand.of(owner))")
34	    @Mapping(target = "ownerSegment", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerSegment.of(owner))")
35	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerTelephoneDisplay.of(owner))")
36	    @Mapping(target = "salutation", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerSalutation.of(owner))")
37	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /** Groups the owner's version-2 identifiers into the nested {@code identity} object. */
41	    default OwnerIdentityDto toIdentity(Owner owner) {
42	        OwnerIdentityDto identity = new OwnerIdentityDto();
43	        identity.setMemberId(owner.getCustomerCode());
44	        identity.setHouseholdId(OwnerIdentityKey.householdId(owner.getLastName(), owner.getPostcode()));
45	        identity.setIdentityKey(OwnerIdentityKey.of(owner));
46	        return identity;
47	    }
48	
49	    Owner toOwner(OwnerDto ownerDto);
50	
51	    @Mapping(target = "id", ignore = true)
52	    @Mapping(target = "pets", ignore = true)
53	    Owner toOwner(OwnerFieldsDto ownerDto);
54	
55	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
56	
57	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
58	
59	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
60	        OwnerPageDto ownerPageDto = new OwnerPageDto();
61	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
62	        ownerPageDto.setPage(ownerPage.getNumber());
63	        ownerPageDto.setSize(ownerPage.getSize());
64	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
65	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
66	        return ownerPageDto;
67	    }
68	}
