35	/**
36	 * Normalizes an owner's telephone to E.164 before the request reaches the controller: a
37	 * leading '+' keeps its country code, otherwise country code '+61' is assumed and a single
38	 * leading '0' dropped; spaces, dashes and brackets are stripped and 8 to 15 digits must
39	 * remain after the '+' or the request is rejected with a 400. Kept as its own advice so
40	 * this rule stays a small, self-contained unit rather than growing the controller or another
41	 * handler.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerTelephoneNormalizationAdvice extends RequestBodyAdviceAdapter {
46	
47	    @Override
48	    public boolean supports(MethodParameter methodParameter, Type targetType,
49	                            Class<? extends HttpMessageConverter<?>> converterType) {
50	        return OwnerFieldsDto.class.equals(targetType);
51	    }
52	
53	    @Override
54	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
55	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
56	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
57	        owner.setTelephone(toE164(owner.getTelephone()));
58	        checkNationalLength(owner.getTelephone());
59	        return body;
60	    }
61	
62	    /** National-number digit count required per E.164 country code. */
63	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("61", 9, "1", 10);
64	
65	    /**
66	     * Rejects a telephone whose national-number length is wrong for its country code:
67	     * '+61' requires 9 national digits and '+1' requires 10. Country codes not listed
68	     * here keep only the generic E.164 length rule applied in {@link #toE164}.
69	     */
70	    private static void checkNationalLength(String e164) {
71	        String digits = e164.substring(1);
72	        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
73	            String code = country.getKey();
74	            if (digits.startsWith(code) && digits.length() - code.length() != country.getValue()) {
75	                throw new InvalidTelephoneException();
76	            }
77	        }
78	    }
79	
80	    /** Converts a telephone to its E.164 string, or throws when no valid form exists. */
81	    static String toE164(String telephone) {
82	        String trimmed = telephone == null ? "" : telephone.trim();
83	        String digits = trimmed.replaceAll("\\D", "");
84	        if (!trimmed.startsWith("+")) {
85	            if (digits.startsWith("0")) {
86	                digits = digits.substring(1);
87	            }
88	            digits = "61" + digits;
89	        }
90	        if (digits.length() < 8 || digits.length() > 15) {
91	            throw new InvalidTelephoneException();
92	        }
93	        return "+" + digits;
94	    }
95	
96	    @ExceptionHandler(InvalidTelephoneException.class)
97	    @ResponseBody
98	    public ResponseEntity<String> handleInvalidTelephone(InvalidTelephoneException e) {
99	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
100	    }
101	
102	    /** Signals a telephone that cannot form a valid E.164 number. */
103	    static class InvalidTelephoneException extends RuntimeException {
104	
105	        InvalidTelephoneException() {
106	            super("telephone must form a valid E.164 number");
107	        }
108	    }
109	}
