44	@ControllerAdvice
45	@Order(Ordered.HIGHEST_PRECEDENCE)
46	public class OwnerCityCapacityAdvice extends RequestBodyAdviceAdapter {
47	
48	    private static final int CITY_CAPACITY = 50;
49	
50	    private final ClinicService clinicService;
51	
52	    public OwnerCityCapacityAdvice(ClinicService clinicService) {
53	        this.clinicService = clinicService;
54	    }
55	
56	    @Override
57	    public boolean supports(MethodParameter methodParameter, Type targetType,
58	                            Class<? extends HttpMessageConverter<?>> converterType) {
59	        Method method = methodParameter.getMethod();
