54	    @Override
55	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
56	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
57	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
58	        if (isDisposable(owner.getEmail())) {
59	            throw new DisposableEmailException();
