45	/**
46	 * Makes owner creation idempotent per {@code Idempotency-Key} header. The first create that
47	 * carries a key records key -> assigned owner id (response side); a later create repeating a
48	 * seen key is answered with the originally created owner and 200, short-circuiting before the
49	 * body is even read so none of the other create rules (including duplicate-identity 409) run.
50	 * Kept as its own small advice so the rule stays a self-contained unit.
51	 */
52	@ControllerAdvice
53	@Order(Ordered.HIGHEST_PRECEDENCE)
54	public class OwnerIdempotentCreateAdvice extends RequestBodyAdviceAdapter
55	        implements ResponseBodyAdvice<Object> {
56	
57	    private static final String KEY_HEADER = "Idempotency-Key";
58	
59	    private final Map<String, Integer> keyToOwnerId = new ConcurrentHashMap<>();
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    public OwnerIdempotentCreateAdvice(ClinicService clinicService, OwnerMapper ownerMapper) {
66	        this.clinicService = clinicService;
67	        this.ownerMapper = ownerMapper;
68	    }
69	
70	    private static boolean isAddOwner(Method method) {
71	        return method != null && "addOwner".equals(method.getName());
72	    }
73	
74	    @Override
75	    public boolean supports(MethodParameter methodParameter, Type targetType,
76	                            Class<? extends HttpMessageConverter<?>> converterType) {
77	        return OwnerFieldsDto.class.equals(targetType) && isAddOwner(methodParameter.getMethod());
78	    }
79	
80	    @Override
81	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
82	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
83	        String key = inputMessage.getHeaders().getFirst(KEY_HEADER);
84	        Integer ownerId = key == null ? null : keyToOwnerId.get(key);
85	        if (ownerId != null) {
86	            throw new IdempotentReplayException(ownerId);
87	        }
88	        return inputMessage;
89	    }
90	
91	    @Override
92	    public boolean supports(MethodParameter returnType, Class<? extends HttpMessageConverter<?>> converterType) {
93	        return isAddOwner(returnType.getMethod());
94	    }
95	
96	    @Override
97	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
98	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
99	                                  ServerHttpRequest request, ServerHttpResponse response) {
100	        String key = request.getHeaders().getFirst(KEY_HEADER);
101	        if (key != null && body instanceof OwnerDto dto && dto.getId() != null) {
102	            keyToOwnerId.putIfAbsent(key, dto.getId());
103	        }
104	        return body;
105	    }
106	
107	    @ExceptionHandler(IdempotentReplayException.class)
108	    @ResponseBody
109	    public ResponseEntity<OwnerDto> handleReplay(IdempotentReplayException e) {
110	        Owner owner = clinicService.findOwnerById(e.ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    /** Signals that a create repeats an already-seen key and must replay owner {@code ownerId}. */
118	    static class IdempotentReplayException extends RuntimeException {
119	
120	        final Integer ownerId;
121	
122	        IdempotentReplayException(Integer ownerId) {
123	            this.ownerId = ownerId;
124	        }
125	    }
126	}
