18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Set;
22	
23	/**
24	 * Resolves the effective registration date to a business day: a supplied date is used as-is,
25	 * a missing one defaults to the server's current date, and either way a Saturday, Sunday or
26	 * listed public holiday is rolled forward to the next non-holiday business day. Kept as one
27	 * tiny, self-contained unit so every rule that depends on the registration date shares the
28	 * same adjustment without growing a handler.
29	 */
30	final class RegistrationBusinessDay {
31	
32	    private static final Set<LocalDate> HOLIDAYS = Set.of(
33	        LocalDate.of(2026, 1, 1),
34	        LocalDate.of(2026, 1, 26),
35	        LocalDate.of(2026, 4, 25),
36	        LocalDate.of(2026, 12, 25),
37	        LocalDate.of(2026, 12, 28));
38	
39	    private RegistrationBusinessDay() {
40	    }
41	
42	    static LocalDate effective(LocalDate supplied) {
43	        LocalDate date = supplied == null ? LocalDate.now() : supplied;
44	        while (isNonBusinessDay(date)) {
45	            date = date.plusDays(1);
46	        }
47	        return date;
48	    }
49	
50	    private static boolean isNonBusinessDay(LocalDate date) {
51	        DayOfWeek day = date.getDayOfWeek();
52	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY || HOLIDAYS.contains(date);
53	    }
54	}
