26	/**
27	 * Makes a freshly-computed customerCode unique: if it already belongs to another owner, appends
28	 * '-<n>' with the smallest n >= 2 that is free. Kept as its own small unit so the collision rule
29	 * stays self-contained rather than growing the aspect that computes the base code.
30	 */
31	@Component
32	public class OwnerCustomerCodeDeduplicator {
33	
34	    private final OwnerRepository owners;
35	
36	    public OwnerCustomerCodeDeduplicator(OwnerRepository owners) {
37	        this.owners = owners;
38	    }
39	
40	    public String unique(String base) {
41	        Set<String> used = new HashSet<>();
42	        for (Owner o : owners.findAll()) {
43	            used.add(o.getCustomerCode());
44	        }
45	        String code = base;
46	        for (int n = 2; used.contains(code); n++) {
47	            code = base + "-" + n;
48	        }
49	        return code;
50	    }
51	}
