33	/**
34	 * Flags a returned owner as a suspected duplicate (soft match) of an earlier owner. Now that the
35	 * identity key includes the telephone, two owners with the same {@code soundex(lastName)} and
36	 * postcode but different telephones share no identity key and are both created; the later one is a
37	 * soft match of the earlier. Kept as its own small advice so this rule stays a self-contained unit.
38	 */
39	@ControllerAdvice
40	public class OwnerPossibleDuplicateAdvice implements ResponseBodyAdvice<Object> {
41	
42	    private final ClinicService clinicService;
43	
44	    public OwnerPossibleDuplicateAdvice(ClinicService clinicService) {
45	        this.clinicService = clinicService;
46	    }
47	
48	    @Override
49	    public boolean supports(MethodParameter returnType,
50	                            Class<? extends HttpMessageConverter<?>> converterType) {
51	        return true;
52	    }
53	
54	    @Override
55	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
56	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
57	                                  ServerHttpRequest request, ServerHttpResponse response) {
58	        if (body instanceof OwnerDto owner) {
59	            Owner match = softMatch(owner);
60	            owner.setPossibleDuplicate(match != null);
61	            owner.setPossibleDuplicateOf(match == null ? null : match.getId());
62	        }
63	        return body;
64	    }
65	
66	    /** The earliest non-deleted owner with the same soundex(lastName) and postcode but a
67	     *  different identity key, or {@code null} when none exists. */
68	    private Owner softMatch(OwnerDto owner) {
69	        String soundex = OwnerSoundex.soundex(owner.getLastName());
70	        return clinicService.findAllOwners().stream()
71	            .filter(o -> !Boolean.TRUE.equals(o.getDeleted()))
72	            .filter(o -> owner.getId() != null && o.getId() < owner.getId())
73	            .filter(o -> Objects.equals(o.getPostcode(), owner.getPostcode()))
74	            .filter(o -> soundex.equals(OwnerSoundex.soundex(o.getLastName())))
75	            .filter(o -> !OwnerIdentityKey.of(o).equals(owner.getIdentity().getIdentityKey()))
76	            .min(Comparator.comparing(Owner::getId))
77	            .orElse(null);
78	    }
79	}
