31	/**
32	 * Flags a returned owner as risky when any single signal holds: it is a possible duplicate,
33	 * its email domain is disposable-adjacent (shares a label with a blocked disposable domain,
34	 * e.g. a different TLD or a subdomain), or its city is over its soft capacity. The duplicate
35	 * and capacity signals are delegated to their own advices so this rule adds nothing but the
36	 * combination and stays a small, self-contained unit.
37	 */
38	@ControllerAdvice
39	public class OwnerRiskFlagAdvice implements ResponseBodyAdvice<Object> {
40	
41	    private static final Set<String> DISPOSABLE_LABELS =
42	        Set.of("mailinator", "tempmail", "guerrillamail");
43	
44	    private final OwnerPossibleDuplicateAdvice duplicateAdvice;
45	
46	    private final OwnerCapacityWarningAdvice capacityAdvice;
47	
48	    public OwnerRiskFlagAdvice(OwnerPossibleDuplicateAdvice duplicateAdvice,
49	                               OwnerCapacityWarningAdvice capacityAdvice) {
50	        this.duplicateAdvice = duplicateAdvice;
51	        this.capacityAdvice = capacityAdvice;
52	    }
53	
54	    @Override
55	    public boolean supports(MethodParameter returnType,
56	                            Class<? extends HttpMessageConverter<?>> converterType) {
57	        return true;
58	    }
59	
60	    @Override
61	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
62	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
63	                                  ServerHttpRequest request, ServerHttpResponse response) {
64	        if (body instanceof OwnerDto owner) {
65	            duplicateAdvice.beforeBodyWrite(body, returnType, selectedContentType,
66	                selectedConverterType, request, response);
67	            capacityAdvice.beforeBodyWrite(body, returnType, selectedContentType,
68	                selectedConverterType, request, response);
69	            owner.setRiskFlag(Boolean.TRUE.equals(owner.getPossibleDuplicate())
70	                || Boolean.TRUE.equals(owner.getCapacityWarning())
71	                || isDisposableAdjacent(owner.getEmail()));
72	        }
73	        return body;
74	    }
75	
76	    private boolean isDisposableAdjacent(String email) {
77	        if (email == null) {
78	            return false;
79	        }
80	        int at = email.lastIndexOf('@');
81	        if (at < 0) {
82	            return false;
83	        }
84	        String domain = email.substring(at + 1).strip().toLowerCase(Locale.ROOT);
85	        for (String label : domain.split("\\.")) {
86	            if (DISPOSABLE_LABELS.contains(label)) {
87	                return true;
88	            }
89	        }
90	        return false;
91	    }
92	}
