56	        if (body instanceof OwnerDto owner && owner.getMembershipLevel() != null) {
57	            OptionalInt ceiling = householdCeiling(owner);
58	            if (ceiling.isPresent()) {
59	                owner.setMembershipLevel(Math.min(owner.getMembershipLevel(), ceiling.getAsInt()));
60	            }
61	        }
62	        return body;
63	    }
64	
65	    private OptionalInt householdCeiling(OwnerDto owner) {
66	        return clinicService.findAllOwners().stream()
67	            .filter(other -> !Boolean.TRUE.equals(other.getDeleted()))
68	            .filter(other -> other.getId() != null && owner.getId() != null && other.getId() < owner.getId())
69	            .filter(other -> owner.getIdentity().getHouseholdId()
70	                .equals(OwnerIdentityKey.householdId(other.getLastName(), other.getPostcode())))
71	            .mapToInt(other -> OwnerMembershipLevel.of(other) + 1)
72	            .max();
73	    }
74	}
