27	/**
28	 * Derives an owner's unified {@code memberId} '<REGION>V2<FY><HASH8><CHK>': the region code (from the
29	 * postcode band, else "UNKNOWN") carrying the fixed 'V2' identity-version tag, the 2-digit fiscal
30	 * year of the registration date, the first 8
31	 * upper-hex characters of SHA-256 over (normalizedTelephone + lastName), and a single Luhn check
32	 * digit over the digits of the preceding segments. Kept as a small standalone unit so the assigning
33	 * aspect, the response mapper and the segment rule all derive the same identity.
34	 */
35	public final class OwnerMemberId {
36	
37	    private OwnerMemberId() {
38	    }
39	
40	    /** Postcode band (4-digit / 100) -> region code. */
41	    private static final Map<Integer, String> REGION = Map.of(20, "NSW", 30, "VIC", 40, "QLD");
42	
43	    /** The region code derived from the owner's postcode band, or "UNKNOWN". */
44	    public static String region(Owner owner) {
45	        String pc = owner.getPostcode();
46	        int band = pc != null && pc.matches("[0-9]{4}") ? Integer.parseInt(pc) / 100 : -1;
47	        return REGION.getOrDefault(band, "UNKNOWN");
48	    }
49	
50	    /** The base memberId before any collision suffix, or {@code null} when the date is absent. */
51	    public static String base(Owner owner) {
52	        LocalDate registered = owner.getRegistrationDate();
53	        if (registered == null) {
54	            return null;
55	        }
56	        String body = region(owner) + "V2" + String.format("%02d", OwnerFiscalYear.yearOf(registered) % 100)
57	            + hash8(owner);
58	        return body + OwnerCheckDigit.luhn(body);
59	    }
60	
61	    private static String hash8(Owner owner) {
62	        try {
63	            byte[] d = MessageDigest.getInstance("SHA-256")
64	                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
65	            return String.format("%02X%02X%02X%02X", d[0], d[1], d[2], d[3]);
66	        }
67	        catch (NoSuchAlgorithmException e) {
68	            throw new IllegalStateException(e);
69	        }
70	    }
71	}
