18	
19	import java.util.Locale;
20	
21	/**
22	 * Computes the standard 4-character Soundex code of a name (first letter followed by three
23	 * digits). Used by the owner identity key and the soft-match rule to group phonetically similar
24	 * last names. Kept as its own small, self-contained unit.
25	 */
26	final class OwnerSoundex {
27	
28	    /** Soundex digit for each letter A-Z ('0' means the letter is dropped). */
29	    private static final String CODES = "01230120022455012623010202";
30	
31	    private OwnerSoundex() {
32	    }
33	
34	    static String soundex(String name) {
35	        String letters = (name == null) ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
36	        if (letters.isEmpty()) {
37	            return "0000";
38	        }
39	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
40	        char previous = codeOf(letters.charAt(0));
41	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
42	            char digit = codeOf(letters.charAt(i));
43	            if (digit != '0' && digit != previous) {
44	                code.append(digit);
45	            }
46	            if (letters.charAt(i) != 'H' && letters.charAt(i) != 'W') {
47	                previous = digit;
48	            }
49	        }
50	        while (code.length() < 4) {
51	            code.append('0');
52	        }
53	        return code.toString();
54	    }
55	
56	    private static char codeOf(char letter) {
57	        return CODES.charAt(letter - 'A');
58	    }
59	}
