21	/**
22	 * Derives an owner's {@code membershipPoints} and the {@code membershipLevel} mapped from
23	 * them. Points start at 0 and add 2 for a present email, 1 for a zero namesakeCount, 2 for
24	 * a household of 3 or more and 3 for tenure over one elapsed fiscal year from the
25	 * registrationDate. The
26	 * level is 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. Kept as a small
27	 * standalone unit so the response mapper can expose both values without growing.
28	 */
29	public final class OwnerMembershipLevel {
30	
31	    private OwnerMembershipLevel() {
32	    }
33	
34	    public static int points(Owner owner) {
35	        return (hasEmail(owner) ? 2 : 0)
36	            + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)
37	            + (largeHousehold(owner) ? 2 : 0)
38	            + (tenured(owner) ? 3 : 0);
39	    }
40	
41	    public static int of(Owner owner) {
42	        int p = points(owner);
43	        return p <= 1 ? 1 : p <= 3 ? 2 : p <= 5 ? 3 : 4;
44	    }
45	
46	    private static boolean largeHousehold(Owner owner) {
47	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
48	    }
49	
50	    private static boolean hasEmail(Owner owner) {
51	        return owner.getEmail() != null && !owner.getEmail().isBlank();
52	    }
53	
54	    private static boolean tenured(Owner owner) {
55	        return OwnerFiscalYear.elapsed(owner) > 1;
56	    }
57	}
