35	import org.springframework.web.util.ContentCachingResponseWrapper;
36	
37	import tools.jackson.databind.ObjectMapper;
38	
39	/**
40	 * Ensures every rejection response (400, 409, 429) leaves the application as an RFC 7807
41	 * {@code application/problem+json} document carrying {@code type}, {@code title},
42	 * {@code status} and {@code detail}. Responses a handler already rendered as problem+json
43	 * are passed through untouched, so this filter only upgrades the plain bodies produced by
44	 * the per-rule request-body advices. Kept as one small filter so no existing handler has
45	 * to grow to learn the problem+json format.
46	 */
47	@Component
48	public class ProblemJsonRejectionFilter extends OncePerRequestFilter {
49	
50	    private static final Set<Integer> REJECTION_STATUSES = Set.of(400, 409, 429);
51	
52	    private final ObjectMapper objectMapper;
53	
54	    public ProblemJsonRejectionFilter(ObjectMapper objectMapper) {
55	        this.objectMapper = objectMapper;
56	    }
57	
58	    @Override
59	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
60	                                    FilterChain filterChain) throws ServletException, IOException {
61	        ContentCachingResponseWrapper wrapper = new ContentCachingResponseWrapper(response);
62	        filterChain.doFilter(request, wrapper);
63	        if (needsUpgrade(wrapper)) {
64	            writeProblemJson(response, wrapper);
65	        }
66	        else {
67	            wrapper.copyBodyToResponse();
68	        }
69	    }
70	
71	    private boolean needsUpgrade(ContentCachingResponseWrapper wrapper) {
72	        String contentType = wrapper.getContentType();
73	        return REJECTION_STATUSES.contains(wrapper.getStatus())
74	            && (contentType == null || !contentType.contains(MediaType.APPLICATION_PROBLEM_JSON_VALUE));
75	    }
76	
77	    private void writeProblemJson(HttpServletResponse response, ContentCachingResponseWrapper wrapper)
78	            throws IOException {
79	        int status = wrapper.getStatus();
80	        String reason = HttpStatus.valueOf(status).getReasonPhrase();
81	        String original = new String(wrapper.getContentAsByteArray(), StandardCharsets.UTF_8).trim();
82	        Map<String, Object> problem = new LinkedHashMap<>();
83	        problem.put("type", URI.create("about:blank").toString());
84	        problem.put("title", reason);
85	        problem.put("status", status);
86	        problem.put("detail", original.isBlank() ? reason : original);
87	        byte[] body = objectMapper.writeValueAsBytes(problem);
88	        response.setStatus(status);
89	        response.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
90	        response.setContentLength(body.length);
91	        response.getOutputStream().write(body);
92	    }
93	}
